#!/usr/bin/env python3
"""one-property-two-spellings.py <seed>: ONE (Structure, name) PAIR REACHED BY TWO KINDS OF WRITE, THROUGH TWO SITES. Objects of ONE Structure, with `x` in one of twelve states beforehand (absent . plain . not enumerable . read-only . not configurable . frozen in all three . an accessor . a getter alone . absent with a setter | a read-only property | a getter alone | a proxy up the chain); kind A through site 1, kind B through site 2 (each site a function of its own in the text), on two objects and on one; five rounds (a table that is entered at the second miss serves from the third on), both orders. Kinds: a plain store . by a written key . by a computed key . a class field (defined over whatever is there) . defineProperty whole | value alone | not enumerable | an accessor . an arrow | a function that captures the object it is stored on . Reflect.set . Object.assign . ??= . += . delete and store . Reflect.defineProperty. LOOKED AT: the descriptor, the order of the keys, the value by name and by key, what it returns if it is a function (is it the object?), what setters and traps up the chain have seen. As plain Bun or a throw."""
import random, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
R = random.Random(seed)
out = []; w = out.append
w('// generated by one-property-two-spellings.py %d' % seed)
w('const seen = [];')
w('const show = v => (typeof v === "function" ? "fn" : typeof v === "object" && v ? "obj" : typeof v === "string" && /=>|function/.test(v) ? "text of a function" : String(v));')
w('const key = ["x"][0];')
w('const look = o => { const d = Object.getOwnPropertyDescriptor(o, "x"); let s = !d ? "none" : ("value" in d ? "V" + show(d.value) + (d.writable ? "W" : "-") : "A" + (d.get ? "g" : "-") + (d.set ? "s" : "-")) + (d.enumerable ? "E" : "-") + (d.configurable ? "C" : "-"); s += " [" + Object.keys(o).join() + "|" + Reflect.ownKeys(o).join() + "]"; let a, b; try { a = o.x; } catch (e) { a = "T" + e.name; } try { b = o[key]; } catch (e) { b = "T" + e.name; } s += " " + show(a) + (a === b ? "=" : "!" + show(b)); if (typeof a === "function") { try { const r = o.x(); s += " ->" + (r === o ? "self" : show(r)); } catch (e) { s += " ->T" + e.name; } } s += " " + ("x" in o) + Object.prototype.hasOwnProperty.call(o, "x"); if (seen.length) s += " {" + seen.splice(0).join() + "}"; return s; };')
w('const attempt = f => { try { const r = f(); return r === undefined ? "" : "r" + show(r) + " "; } catch (e) { return "T" + e.name + " "; } };')
w('class Back { constructor(o) { return o; } }')
STATES = [
 ('absent', 'const o = { a: 1, b: 2 };', None), ('plain', 'const o = { a: 1, x: 0, b: 2 };', None),
 ('not enumerable', 'const o = { a: 1 }; Object.defineProperty(o, "x", { value: 0, writable: true, enumerable: false, configurable: true }); o.b = 2;', None),
 ('read-only', 'const o = { a: 1 }; Object.defineProperty(o, "x", { value: 0, writable: false, enumerable: true, configurable: true }); o.b = 2;', None),
 ('not configurable', 'const o = { a: 1 }; Object.defineProperty(o, "x", { value: 0, writable: true, enumerable: true, configurable: false }); o.b = 2;', None),
 ('fixed', 'const o = { a: 1 }; Object.defineProperty(o, "x", { value: 0 }); o.b = 2;', None),
 ('an accessor', 'const o = { a: 1, get x() { return "got"; }, set x(v) { seen.push("own set " + show(v)); }, b: 2 };', None),
 ('a getter alone', 'const o = { a: 1, get x() { return "got"; }, b: 2 };', None),
 ('a setter above', 'const o = Object.create(PROTO); o.a = 1; o.b = 2;', '{ get x() { return "above"; }, set x(v) { seen.push("set above " + show(v)); } }'),
 ('read-only above', 'const o = Object.create(PROTO); o.a = 1; o.b = 2;', 'Object.defineProperty({}, "x", { value: "ro above", writable: false, enumerable: true, configurable: true })'),
 ('a getter alone above', 'const o = Object.create(PROTO); o.a = 1; o.b = 2;', '{ get x() { return "above"; } }'),
 ('plain above', 'const o = Object.create(PROTO); o.a = 1; o.b = 2;', '{ x: "plain above" }'),
 ('a proxy above', 'const o = Object.create(PROTO); o.a = 1; o.b = 2;', 'new Proxy({}, { set(t, k, v, r) { seen.push("trap set " + String(k)); return Reflect.set(t, k, v, r); }, get(t, k, r) { return typeof k === "string" && k === "x" ? "trapped" : Reflect.get(t, k, r); }, has(t, k) { return Reflect.has(t, k); } })'),
 ('not extensible, absent', 'const o = { a: 1, b: 2 }; Object.preventExtensions(o);', None),
 ('sealed, plain', 'const o = { a: 1, x: 0, b: 2 }; Object.seal(o);', None),
 ('many properties', 'const o = { a: 1, b: 2 }; for (let i = 0; i < 9; i++) o["p" + i] = i;', None),
]
KINDS = [
 ('store', 'o.x = v;'), ('written key', 'o["x"] = v;'), ('computed key', 'o[key] = v;'),
 ('class field', 'new (class extends Back { x = v; })(o);'), ('class field of a class outside', None),
 ('define whole', 'Object.defineProperty(o, "x", { value: v, writable: true, enumerable: true, configurable: true });'), ('define value alone', 'Object.defineProperty(o, "x", { value: v });'),
 ('define hidden', 'Object.defineProperty(o, "x", { value: v, writable: true, enumerable: false, configurable: true });'), ('define accessor', 'Object.defineProperty(o, "x", { get() { return "defined " + v; }, enumerable: true, configurable: true });'),
 ('arrow that captures it', 'o.x = () => o;'), ('function that captures it', 'o.x = function () { return o; };'), ('arrow that captures both', 'o.x = () => (v, o);'), ('arrow that captures nothing', 'o.x = () => 7;'),
 ('Reflect.set', 'return Reflect.set(o, "x", v);'), ('Object.assign', 'Object.assign(o, { x: v });'), ('??=', 'o.x ??= v;'), ('+=', 'o.x += 1;'), ('delete and store', 'delete o.x; o.x = v;'),
 ('Reflect.defineProperty', 'return Reflect.defineProperty(o, "x", { value: v, writable: true, enumerable: true, configurable: true });'), ('store of undefined', 'o.x = undefined;'), ('three stores in a row', 'o.w = v; o.x = v; o.y = v;'), ('a run with an arrow', 'o.w = v; o.x = () => o; o.y = v;'),
]
N = 46
for n in range(N):
    s = R.choice(STATES); a, b = R.sample(KINDS, 2) if R.random() < 0.9 else [R.choice(KINDS)] * 2
    if s[2]: w('const proto%d = %s;' % (n, s[2]))
    w('function make%d() { %s return o; }' % (n, s[1].replace('PROTO', 'proto%d' % n)))
    for name, k in (('A', a), ('B', b)):
        if k[1] is None:
            w('class Field%s%d extends Back { x = "field"; }' % (name, n)); w('function site%s%d(o, v) { new Field%s%d(o); }' % (name, n, name, n))
        else: w('function site%s%d(o, v) { %s }' % (name, n, k[1]))
    first, second = ('A', 'B') if R.random() < 0.5 else ('B', 'A')
    w('for (let round = 0; round < 5; round++) { const p = make%d(), q = make%d(), both = make%d(), other = make%d(); let s = "%d %s | %s | %s round " + round + ": "; s += attempt(() => site%s%d(p, round)) + look(p) + " ; " + attempt(() => site%s%d(q, round)) + look(q) + " ; " + attempt(() => site%s%d(both, round)) + attempt(() => site%s%d(both, round + 10)) + look(both) + " ; " + attempt(() => site%s%d(other, round)) + attempt(() => site%s%d(other, round + 10)) + look(other); console.log(s); }' % (n, n, n, n, n, s[0], a[0], b[0], first, n, second, n, first, n, second, n, second, n, first, n))
print('\n'.join(out))
